    correction: [{"quoi":"نترجم","math":"المسافة تقسم 208 و 130، إذن هي قاسم مشترك لهما"},{"quoi":"نفكّك إلى عوامل أوّلية","math":"<span dir=\"ltr\" class=\"expr\">208 = 2<sup>4</sup> × 13</span> و <span dir=\"ltr\" class=\"expr\">130 = 2 × 5 × 13</span>"},{"quoi":"ق.م.أ","math":"<span dir=\"ltr\" class=\"expr\">2 × 13 = 26</span>"},{"quoi":"القيم الممكنة = قواسم 26","math":"{ 1 ; 2 ; 13 ; 26 } بالمتر"},{"quoi":"المحصورة بين 20 و 30","math":"<span dir=\"ltr\" class=\"expr\">= 26</span> متر"},{"quoi":"نحسب المحيط","math":"<span dir=\"ltr\" class=\"expr\">2 × (208 + 130) = 676</span>"},{"quoi":"عدد الأشجار","math":"<span dir=\"ltr\" class=\"expr\">676 : 26 = 26</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">= 26</span>"}],
